 private const string LiveSourceSelect="SELECT id,name,enabled,revision,tuners,created_by,next_sync,last_sync,last_error,public_preset,(SELECT COUNT(*) FROM live_channels c WHERE c.source_id=live_sources.id AND c.available=1) FROM live_sources";
 private static LiveSource ReadLiveSource(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetBoolean(2),r.GetInt32(3),r.GetInt32(4),r.GetString(5),r.GetString(6),Text(r,7),Text(r,8),Text(r,9),r.GetInt32(10));
 public IReadOnlyList<LiveSource> LiveSources(){using var db=Open();return Query(db,LiveSourceSelect+" ORDER BY name",ReadLiveSource);}
 public LiveSource GetLiveSource(string id){using var db=Open();return Query(db,LiveSourceSelect+" WHERE id=$id",ReadLiveSource,("$id",id)).FirstOrDefault()??throw new DomainException("TV kaynağı bulunamadı.",404);}
 public string LiveSourceSecret(string id){using var db=Open();return Scalar(db,"SELECT protected_input FROM live_sources WHERE id=$id",("$id",id)) as string??throw new DomainException("TV kaynağı bulunamadı.",404);}
 public LiveSource SaveLiveSource(string? id,LiveSourceInput input,string secret,Account actor,string? presetId=null,bool clearPreset=false)
 {lock(_writeGate){if(!actor.IsAdmin||GetAccount(actor.Id) is not{Enabled:true,IsAdmin:true})throw new DomainException("TV kaynağı yönetici gerektirir.",403);using var db=Open();if(id is null&&presetId is not null&&Scalar(db,"SELECT id FROM live_sources WHERE public_preset=$preset",("$preset",presetId)) is string existing)return GetLiveSource(existing);var old=id is null?null:GetLiveSource(id);if((old?.Revision??0)!=input.ExpectedRevision)throw new DomainException("TV kaynağı değişti.",409);if(old is null&&LiveSources().Count>=20)throw new DomainException("En fazla 20 TV kaynağı eklenebilir.");id??=Guid.NewGuid().ToString("N");Execute(db,"INSERT INTO live_sources(id,name,protected_input,enabled,tuners,created_by,next_sync,public_preset) VALUES($id,$name,$input,$enabled,$tuners,$user,$now,$preset) ON CONFLICT(id) DO UPDATE SET name=$name,protected_input=$input,enabled=$enabled,tuners=$tuners,revision=revision+1,next_sync=$now,last_error=NULL,public_preset=CASE WHEN $clear=1 THEN NULL ELSE public_preset END",("$id",id),("$name",input.Name),("$input",secret),("$enabled",input.Enabled),("$tuners",input.Tuners),("$user",actor.Id),("$now",Now()),("$preset",presetId),("$clear",clearPreset));return GetLiveSource(id);}}
 private const string LiveChannelSelect="SELECT c.id,c.source_id,c.name,c.group_name,COALESCE(c.epg_override,c.epg_id),CASE WHEN c.protected_logo IS NOT NULL THEN 'managed' ELSE c.logo END,c.radio,c.enabled,c.available,c.minimum_age,c.ordinal FROM live_channels c";
 private static LiveChannel ReadLiveChannel(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),Text(r,4),Text(r,5),r.GetBoolean(6),r.GetBoolean(7),r.GetBoolean(8),r.IsDBNull(9)?null:r.GetInt32(9),r.GetInt32(10));
 public IReadOnlyList<LiveChannel> LiveChannels(Account actor,bool all=false){using var db=Open();return Query(db,LiveChannelSelect+" JOIN live_sources s ON s.id=c.source_id WHERE ($all=1 OR s.enabled=1 AND c.enabled=1 AND c.available=1) ORDER BY c.ordinal,c.name LIMIT 10000",ReadLiveChannel,("$all",all&&actor.IsAdmin)).Where(channel=>CanWatchChannel(channel,actor)).ToArray();}
 public LiveChannel GetLiveChannel(string id){using var db=Open();return Query(db,LiveChannelSelect+" WHERE c.id=$id",ReadLiveChannel,("$id",id)).FirstOrDefault()??throw new DomainException("Kanal bulunamadı.",404);}
 public bool CanWatchChannel(LiveChannel channel,Account actor)
 {if(actor.Enabled&&(actor.IsAdmin||actor.MaximumAge is null))return true;var programme=LiveGuide(channel.Id,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow.AddSeconds(1)).FirstOrDefault();var age=channel.MinimumAge is{}a&&programme?.MinimumAge is{}b?Math.Max(a,b):channel.MinimumAge??programme?.MinimumAge;return actor.Enabled&&(actor.MaximumAge is null||age is{}value&&value<=actor.MaximumAge||age is null&&actor.AllowUnrated);}
 public LiveChannel RequireLiveChannel(string id,Account actor){var channel=GetLiveChannel(id);if(!channel.Enabled||!channel.Available||!GetLiveSource(channel.SourceId).Enabled||!CanWatchChannel(channel,actor))throw new DomainException("Kanal çevrimdışı veya profil erişimi dışında.",403);return channel;}
 public string LiveChannelSecret(string id){using var db=Open();return Scalar(db,"SELECT protected_url FROM live_channels WHERE id=$id",("$id",id)) as string??throw new DomainException("Kanal bulunamadı.",404);}
 public string? LiveChannelHeadersSecret(string id){using var db=Open();return Scalar(db,"SELECT protected_headers FROM live_channels WHERE id=$id",("$id",id)) as string;}
 public string? LiveChannelLogoSecret(string id){using var db=Open();return Scalar(db,"SELECT protected_logo FROM live_channels WHERE id=$id",("$id",id)) as string;}
 public void SetLiveChannel(string id,ChannelInput input){if(input.MinimumAge is<0 or>21||input.Ordinal is<0 or>10000||input.EpgId?.Length>300)throw new DomainException("Kanal ayarları geçersiz.");lock(_writeGate){using var db=Open();Execute(db,"UPDATE live_channels SET enabled=$enabled,minimum_age=$age,ordinal=$order,epg_override=CASE WHEN $clear=1 THEN NULL ELSE COALESCE($epg,epg_override) END WHERE id=$id",("$id",id),("$enabled",input.Enabled),("$age",input.MinimumAge),("$order",input.Ordinal),("$clear",input.ClearEpgOverride),("$epg",input.EpgId));}}
 public IReadOnlyList<LiveChannel> SyncLiveChannels(LiveSource source,ParsedChannel[] channels,Func<string,string> protect)
 {
  lock(_writeGate){if(GetLiveSource(source.Id).Revision!=source.Revision)throw new DomainException("TV kaynağı değişti.",409);using var db=Open();using var tx=db.BeginTransaction();MusicSql(db,tx,"UPDATE live_channels SET available=0 WHERE source_id=$id",("$id",source.Id));foreach(var channel in channels)
    {var id=PlaylistGuide.Id(source.Id+channel.Key);MusicSql(db,tx,"INSERT INTO live_channels(id,source_id,source_key,name,group_name,epg_id,protected_logo,protected_url,radio,ordinal,protected_headers,search_text) VALUES($id,$source,$key,$name,$group,$epg,$logo,$url,$radio,$order,$headers,$search) ON CONFLICT(source_id,source_key) DO UPDATE SET name=$name,group_name=$group,epg_id=$epg,logo=NULL,protected_logo=$logo,protected_url=$url,radio=$radio,available=1,protected_headers=$headers,search_text=$search",("$id",id),("$source",source.Id),("$key",channel.Key),("$name",channel.Name),("$group",channel.Group),("$epg",channel.EpgId),("$logo",channel.Logo is null?null:protect(channel.Logo)),("$url",protect(channel.Url)),("$radio",channel.Radio),("$order",channel.Ordinal),("$headers",channel.Headers is{Count:>0}?protect(System.Text.Json.JsonSerializer.Serialize(channel.Headers)):null),("$search",MediaPaths.SearchKey(channel.Name+" "+channel.Group)));}tx.Commit();return Query(db,LiveChannelSelect+" WHERE c.source_id=$id",ReadLiveChannel,("$id",source.Id));}
 }
 public void SaveLiveGuide(LiveSource source,LiveProgramme[] programmes)
 {lock(_writeGate){if(GetLiveSource(source.Id).Revision!=source.Revision)throw new DomainException("EPG kaynağı değişti.",409);using var db=Open();using var tx=db.BeginTransaction();foreach(var item in programmes)MusicSql(db,tx,"INSERT INTO live_programmes(id,channel_id,starts_at,ends_at,title,title_key,description,episode_key,repeat,minimum_age) VALUES($id,$channel,$start,$end,$title,$titleKey,$description,$episode,$repeat,$age) ON CONFLICT(channel_id,starts_at) DO UPDATE SET ends_at=$end,title=$title,title_key=$titleKey,description=$description,episode_key=$episode,repeat=$repeat,minimum_age=$age",("$id",item.Id),("$channel",item.ChannelId),("$start",item.StartsAt),("$end",item.EndsAt),("$title",item.Title),("$titleKey",MediaPaths.SearchKey(item.Title)),("$description",item.Description),("$episode",item.EpisodeKey),("$repeat",item.Repeat),("$age",item.MinimumAge));MusicSql(db,tx,"DELETE FROM live_programmes WHERE ends_at<$old AND NOT EXISTS(SELECT 1 FROM dvr_recordings r WHERE r.programme_id=live_programmes.id)",("$old",DateTimeOffset.UtcNow.AddDays(-2).ToString("O")));tx.Commit();}}
 private const string ProgrammeSelect="SELECT id,channel_id,starts_at,ends_at,title,description,episode_key,repeat,minimum_age FROM live_programmes";
 private static LiveProgramme ReadProgramme(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.IsDBNull(7)?null:r.GetBoolean(7),r.IsDBNull(8)?null:r.GetInt32(8));
 public IReadOnlyList<LiveProgramme> LiveGuide(string channel,DateTimeOffset from,DateTimeOffset to){using var db=Open();return Query(db,ProgrammeSelect+" WHERE channel_id=$channel AND starts_at<$to AND ends_at>$from ORDER BY starts_at LIMIT 500",ReadProgramme,("$channel",channel),("$from",from.ToString("O")),("$to",to.ToString("O")));}
 public LiveProgramme GetLiveProgramme(string id){using var db=Open();return Query(db,ProgrammeSelect+" WHERE id=$id",ReadProgramme,("$id",id)).FirstOrDefault()??throw new DomainException("Program bulunamadı.",404);}
 public void CompleteLiveSync(LiveSource source,string? error){lock(_writeGate){using var db=Open();Execute(db,"UPDATE live_sources SET next_sync=$next,last_sync=CASE WHEN $error IS NULL THEN $now ELSE last_sync END,last_error=$error WHERE id=$id AND revision=$revision",("$id",source.Id),("$revision",source.Revision),("$next",DateTimeOffset.UtcNow.AddHours(error is null?6:1).ToString("O")),("$now",Now()),("$error",error));}}
 private const string TvSessionSelect="SELECT id,user_id,login_id,device_id,channel_id,source_revision,status,created_at,last_seen,error,client_id,client_revision FROM live_sessions";
 private static LiveSession ReadTvSession(Microsoft.Data.Sqlite.SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetInt32(5),r.GetString(6),r.GetString(7),r.GetString(8),Text(r,9),Text(r,10),r.GetInt64(11));
 public LiveSession? GetLiveSession(string id){using var db=Open();return Query(db,TvSessionSelect+" WHERE id=$id",ReadTvSession,("$id",id)).FirstOrDefault();}
 public IReadOnlyList<LiveSession> ActiveLiveSessions(){using var db=Open();return Query(db,TvSessionSelect+" WHERE status IN ('starting','active')",ReadTvSession);}
 public int SourceTunerUse(string source){using var db=Open();return Convert.ToInt32(Scalar(db,"SELECT (SELECT COUNT(*) FROM live_sessions s JOIN live_channels c ON c.id=s.channel_id WHERE c.source_id=$source AND s.status IN ('starting','active'))+(SELECT COUNT(*) FROM dvr_recordings r JOIN live_channels c ON c.id=r.channel_id WHERE c.source_id=$source AND r.status='recording')",("$source",source)));}
 public LiveSession AdmitLiveSession(string channelId,PlaybackActor actor,string? clientId=null,long revision=1)
 {
  if(clientId is not null){_=AppFiles.Id(clientId);if(revision is <1 or >9_007_199_254_740_991)throw new DomainException("TV oynatma komutu geçersiz.");}
  lock(_writeGate){var user=RequirePlaybackActor(actor);var channel=RequireLiveChannel(channelId,user);var source=GetLiveSource(channel.SourceId);var previous=clientId is null?[]:ActiveLiveSessions().Where(s=>s.LoginId==actor.LoginId&&s.ClientId==clientId).ToArray();
   if(SourceTunerUse(source.Id)-previous.Count(s=>GetLiveChannel(s.ChannelId).SourceId==source.Id)>=source.Tuners)throw new DomainException("TV kaynağının tuner/akış kapasitesi dolu.",429);
   using var db=Open();if(clientId is not null){var prior=Scalar(db,"SELECT revision FROM playback_intents WHERE login_id=$login AND client_id=$client",("$login",actor.LoginId),("$client",clientId));if(prior is not null&&Convert.ToInt64(prior)>=revision)throw new DomainException("Daha yeni oynatma komutu zaten uygulandı.",409);}
   RequireTransientSlot(actor,clientId);
   if(clientId is not null){ClosePlaybackClient(actor,clientId,revision,DateTimeOffset.UtcNow);foreach(var old in previous)SetLiveSession(old.Id,"closed");foreach(var old in ActiveMusicRadioSessions().Where(s=>s.LoginId==actor.LoginId&&s.ClientId==clientId))CloseMusicRadio(old.Id);}
   var id=Guid.NewGuid().ToString("N");Execute(db,"INSERT INTO live_sessions(id,user_id,login_id,device_id,channel_id,source_revision,status,created_at,last_seen,client_id,client_revision) VALUES($id,$user,$login,$device,$channel,$revision,'starting',$now,$now,$client,$clientRevision)",("$id",id),("$user",user.Id),("$login",actor.LoginId),("$device",actor.DeviceId),("$channel",channel.Id),("$revision",source.Revision),("$now",Now()),("$client",clientId),("$clientRevision",clientId is null?0:revision));return GetLiveSession(id)!;}
 }
 public string[] CloseLiveClient(PlaybackActor actor,string clientId,long revision)
 {lock(_writeGate){ClosePlaybackClient(actor,clientId,revision,DateTimeOffset.UtcNow);var previous=ActiveLiveSessions().Where(s=>s.LoginId==actor.LoginId&&s.ClientId==clientId&&s.ClientRevision<=revision).ToArray();foreach(var old in previous)SetLiveSession(old.Id,"closed");return previous.Select(s=>s.Id).ToArray();}}
 public LiveSession RequireLiveSession(string id,PlaybackActor actor,bool touch=false)
 {lock(_writeGate){var session=GetLiveSession(id)??throw new DomainException("Canlı oynatma bulunamadı.",404);if(session.UserId!=actor.UserId||session.LoginId!=actor.LoginId||session.DeviceId!=actor.DeviceId||session.Status is not("starting" or"active"))throw new DomainException("Canlı oynatma izni sona erdi.",410);var user=RequirePlaybackActor(actor);var channel=RequireLiveChannel(session.ChannelId,user);if(GetLiveSource(channel.SourceId).Revision!=session.SourceRevision||DateTimeOffset.UtcNow-DateTimeOffset.Parse(session.LastSeen)>TimeSpan.FromMinutes(2))throw new DomainException("Canlı kaynak veya oturum değişti.",410);if(touch){using var db=Open();Execute(db,"UPDATE live_sessions SET last_seen=$now WHERE id=$id",("$id",id),("$now",Now()));}return session;}}
  public void SetLiveSession(string id,string status,string? error=null){lock(_writeGate){using var db=Open();Execute(db,"UPDATE live_sessions SET status=$status,error=$error WHERE id=$id",("$id",id),("$status",status),("$error",error));}}
  public void ActivateLiveSession(string id,PlaybackActor actor)
  {lock(_writeGate){_=RequireLiveSession(id,actor);using var db=Open();Execute(db,"UPDATE live_sessions SET status='active',error=NULL WHERE id=$id AND status IN ('starting','active')",("$id",id));}}
 public void RecoverLiveSessions(){lock(_writeGate){using var db=Open();Execute(db,"UPDATE live_sessions SET status='closed',error='Sunucu yeniden başladı.' WHERE status IN ('starting','active'); DELETE FROM live_sessions WHERE status NOT IN ('starting','active') AND created_at<$old",("$old",DateTimeOffset.UtcNow.AddDays(-7).ToString("O")));}}
}
